  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","highlight","hold","wave","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  highlight: "Keynote opener.",
  hold: 18,
  wave: 26,
  fontFamily: "IBM Plex Sans",
  scale: 1,
  delay: 0,
  speed: 1,
};

type IdeaSetElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof IdeaSetBase>;

const IdeaSetInner = forwardRef<
  HTMLDivElement,
  IdeaSetElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<IdeaSet>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <IdeaSetBase
          {...(componentProps as unknown as ComponentProps<typeof IdeaSetBase>)}
        />
      </div>
    </Sequence>
  );
});

export const IdeaSet = Interactive.withSchema({
  Component: IdeaSetInner,
  componentName: "<IdeaSet>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
